import hero from './images/Hero-Banner.png'
import NavigationBar from './components/NavigationBar';
import { useEffect } from 'react'
import Video from './components/Video'
import Paragraph from './components/Paragraph'

function App() {

  useEffect(() => {
    document.body.style.backgroundColor = '#061213'
  })


  return (
    <div className="App">
      <header className="App-header">
        <NavigationBar/>
        <p style={{position: 'absolute', fontSize: 36, fontWeight: 'bolder', color: 'white', top: '150px', left: '20px'}}>QuackNet</p>
        <p style={{position: 'absolute', color: 'white', top: '220px', left: '20px'}}>All of your favorite games on the cloud.</p>
        <img style={{ width: '100%', height: 'auto'}} src={hero} alt="hero banner of the QuackBox"></img>
        <Video/>
        <Paragraph></Paragraph>
      </header>
    </div>
  );
}

export default App;
